// Custom Cloudflare Worker entry.
//
// `opennextjs-cloudflare build` regenerates `.open-next/worker.js` on every
// build and that file only exports a `fetch` handler, so a Cloudflare Cron
// Trigger would have nothing to call. This wrapper keeps the generated worker
// as the request handler and adds a `scheduled` handler that pokes the refresh
// endpoint through the WORKER_SELF_REFERENCE service binding.
//
// wrangler.jsonc points `main` at this file; see the `triggers.crons` entry
// there for the schedule.

// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import openNextWorker from './.open-next/worker.js'

// The generated worker also defines these Durable Objects; re-export them so
// the class bindings stay resolvable.
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
export { BucketCachePurge, DOQueueHandler, DOShardedTagCache } from './.open-next/worker.js'

// The host is ignored for service bindings; the path is what matters.
const REFRESH_URL = 'https://threattrace/api/refresh'

export default {
  fetch: openNextWorker.fetch as typeof openNextWorker.fetch,

  scheduled(_event: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    ctx.waitUntil(
      env.WORKER_SELF_REFERENCE
        .fetch(REFRESH_URL, { method: 'POST' })
        .then((res) => {
          if (!res.ok) console.error(`[threattrace] scheduled refresh returned ${res.status}`)
        })
        .catch((error: unknown) => {
          console.error('[threattrace] scheduled refresh failed:', (error as Error).message)
        }),
    )
  },
}
